/** The coral four-point sparkle from the app icon. */
export function Sparkle({ className, style, still }: SvgProps & { still?: boolean }) {
  const id = useId();
  return (
    <svg viewBox="0 0 24 24" className={cx(!still && "g-spark", className)} style={style} aria-hidden="true">
      <defs>
        <linearGradient id={id} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#FFA267" />
          <stop offset="1" stopColor="#F7715B" />
        </linearGradient>
      </defs>
      <path
        fill={`url(#${id})`}
        d="M12 0c.8 7.5 4.5 11.2 12 12-7.5.8-11.2 4.5-12 12-.8-7.5-4.5-11.2-12-12 7.5-.8 11.2-4.5 12-12z"
      />
    </svg>
  );
}

/* Hand-drawn strokes in the manner of the ring around the app icon.
   They stretch to their box; pathLength=1 lets CSS draw them in. */
export function HandRing({ className, style }: SvgProps) {
  return (
    <svg className={cx("g-hand", className)} style={style} viewBox="0 0 300 120" preserveAspectRatio="none" aria-hidden="true">
      <path pathLength={1} d="M168 9C74 1 9 27 10 62c2 38 72 53 152 51 82-2 130-23 128-55C288 24 214 5 112 13" />
    </svg>
  );
}

