export function AppStoreButton({
  className = "g-btn g-btn--primary",
  label = "Download on the App Store",
}: {
  className?: string;
  label?: string;
}) {
  return (
    <a className={className} href={APP_STORE_URL} target="_blank" rel="noopener noreferrer">
      <AppleLogo />
      <span>{label}</span>
    </a>
  );
}

